#!/usr/bin/env bash
# WI-38 round-2 gate-fix review checks (reviewer, read-only)
cd /repo || exit 1
FILES=".claude/rules/core/execution.md .claude/rules/core/orchestration.md .claude/rules/core/subagent-alignment.md .claude/rules/domains/engineering.md .claude/rules/quality/completion.md .claude/rules/quality/resources/validation-checklist-active.md"

echo "== C1: changed hunks lie only inside paths frontmatter =="
for f in $FILES; do
  end=$(awk 'NR>1 && /^---$/ {print NR; exit}' "$f")
  # line numbers of changed lines in the new file
  changed=$(git diff -U0 -- "$f" | grep -E '^@@' | sed -E 's/^@@ -[0-9,]+ \+([0-9]+)(,([0-9]+))? @@.*/\1 \3/')
  echo "$f frontmatter_end=$end hunks_new=[$changed]"
  echo "  removed_or_added: $(git diff -U0 -- "$f" | grep -E '^[-+][^-+]' | tr '\n' '|')"
done

echo "== C2: YAML frontmatter parses, paths list present, reviewer.md included, no reviewer/** =="
node -e '
const fs=require("fs");
let yaml; try { yaml=require("js-yaml"); } catch(e) { try { yaml=require("yaml"); yaml={load:yaml.parse}; } catch(e2){ console.log("NO_YAML_LIB"); process.exit(2);} }
let bad=0;
for (const f of process.argv.slice(1)) {
  const t=fs.readFileSync(f,"utf8"); const m=t.match(/^---\n([\s\S]*?)\n---\n/);
  if(!m){console.log(f,"NO_FRONTMATTER");bad++;continue;}
  let d; try{ d=yaml.load(m[1]); }catch(e){console.log(f,"YAML_ERR",e.message);bad++;continue;}
  const p=d.paths||[];
  const hasMd=p.includes("agents/reviewer.md"); const hasGlob=p.includes("agents/reviewer/**");
  const dup=p.length-new Set(p).size;
  console.log(f,"paths="+p.length,"reviewer.md="+hasMd,"reviewer/**="+hasGlob,"dups="+dup);
  if(!hasMd||hasGlob||dup) bad++;
}
console.log("C2 bad="+bad); process.exit(bad?1:0);
' $FILES
echo "C2 rc=$?"

echo "== C3: agents/reviewer dir gone, agents/reviewer.md tracked =="
test -e agents/reviewer && echo "agents/reviewer EXISTS" || echo "agents/reviewer absent"
git ls-files --error-unmatch agents/reviewer.md && echo "reviewer.md tracked"

echo "== C4: no line-number change outside frontmatter (numstat) =="
git diff --numstat -- $FILES

echo "== C5: em dashes in added lines =="
git diff -- $FILES | grep -E '^\+[^+]' | grep -c $'\xe2\x80\x94'

echo "== C6: vitest gate + readers =="
npx vitest run --config tests/vitest.config.js tests/v12/rules-paths-globs-resolve.test.js tests/v12/controller-checkpoint-clause-consistency.test.js tests/regressions/skill-refs-current.test.js tests/regressions/validation-checklist-active.test.js tests/v12/graceful-degradation-scope-generalized.test.js tests/v12/playbook-extraction-cohesion.test.js tests/v12/routing-refs-resolve.test.js tests/v12/rules-paths-present.test.js tests/v12/validation-layers-consistent.test.js --reporter=dot
echo "C6 rc=$?"

#!/usr/bin/env bash
