R=/repo
S=$R/cagents-memory/sessions/act_streamline-cleanup-plugin_261111_001
L=$S/outputs/cleanup/allcaps_ledger.tsv
MODE=$1
cd $R
awk -F'\t' -v OFS='\t' -v m="$MODE" 'NR>1 && $1!~/^#/ { for(i=1;i<=8;i++) if($i=="") $i="-";
  if (m=="keep" && $4 ~ /^keep/) print NR"\t"$0;
  else if (m=="lwr" && $4=="lower-with-reason") print NR"\t"$0;
  else if (m=="lower" && $4=="lower" && (NR % 9 == 0)) print NR"\t"$0;
  else if (m=="pinned" && $6!="") print NR"\t"$0;
  else if (m=="designer" && $1 ~ /designer/ && ($3=="MUST" || $3=="NEVER" || $3=="ALWAYS" || $3=="CRITICAL" || $3=="DO NOT" || $3=="NOT")) print NR"\t"$0;
  else if (m=="pairs" && (($1==".claude/rules/core/controllers.md" && ($2==116||$2==624)) || ($1==".claude/rules/core/delegation.md" && $2==161) || ($1=="CLAUDE.md" && ($2==111||$2==76||$2==103)) || ($1==".claude/skills/act/SKILL.md" && $2==169))) print NR"\t"$0;
}' $L | while IFS=$'\t' read -r nr p ln tok cls nt pin own note; do
  base=$(git show 9e387a40:"$p" | sed -n "${ln}p")
  printf -- '--- row %s | %s:%s | %s | %s | pin=%s | %s\n  BASE: %s\n  NEW : %s\n  NOTE: %s\n' "$nr" "$p" "$ln" "$tok" "$cls" "$pin" "$own" "$base" "$nt" "$note"
done

